protocol Visitor { func visitUnknown(_ e: Element) }
protocol UnionVisitor: Visitor { func visitUnion(_ u: UnionShape) }   // extended protocol
extension Visitor { func visitCircle(_ c: Circle) { visitUnknown(c) } } // the default case

struct UnionShape: Element {
    func accept(_ v: any Visitor) {
        if let uv = v as? any UnionVisitor { uv.visitUnion(self) }    // capability cast
        else { v.visitUnknown(self) }                                 // visitor that predates me
    }
}
